     1→import { BaseAbility } from './BaseAbility';
     2→import type { GameSceneAPI } from './types';
     3→
     4→/**
     5→ * 레거시 (UR)
     6→ * - 기본 효과: 게임 시작 시 6초간 금똥 2개씩 내려오는 피버타임 + 황금 빗줄기(D)
     7→ *             + 똥 스폰마다 20% 확률로 랜덤 2개 화염 추적선(B) + 불태워 소멸 (+10점)
     8→ *             + 캐릭터 주변 상시 불꽃 오라(A)
     9→ * - 특수 능력: 500점마다 레거시 모드 10초 발동
    10→ *             — 점수 1.2배 + 화면 전체 불꽃 폭발 + 황금 실루엣(C) + 테두리 글로우
    11→ *             — 불태우기 강화: 40% 확률로 4개 소멸 / 오라 황금빛으로 강화
    12→ */
    13→export class LegacyAbility extends BaseAbility {
    14→  private startFeverActive = false;
    15→  private legacyModeActive = false;
    16→  private accum           = 0;
    17→  private lastLegacyScore = 0;
    18→  private legacyGlow?:       Phaser.GameObjects.Graphics; // 캐릭터 주변 노란 글로우
    19→  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
    20→  private legacyPulseTween?: Phaser.Tweens.Tween;
    21→
    22→  // A: 상시 불꽃 오라 — delta 누산 타이머
    23→  private oraTimer = 0;
    24→  private static readonly ORA_INTERVAL_NORMAL = 220; // ms
    25→  private static readonly ORA_INTERVAL_LEGACY = 110; // ms (레거시 모드 중 더 빠름)
    26→
    27→  // SSJ 오라 — 주기적 redraw로 일렁임 구현
    28→  private auraGfx?: Phaser.GameObjects.Graphics;
    29→  private auraRedrawTimer = 0;
    30→  private static readonly AURA_REDRAW_MS = 80; // ms마다 스파이크 모양 재생성
    31→
    32→  // ── 불꽃 물방울 다각형 좌표 (static 공유) ──────────────────────────
    33→  private static flamePts(w: number, h: number) {
    34→    return [
    35→      { x:  0,         y: -h        },
    36→      { x:  w * 0.55,  y: -h * 0.1  },
    37→      { x:  w * 0.75,  y:  h * 0.35 },
    38→      { x:  w * 0.3,   y:  h        },
    39→      { x: -w * 0.3,   y:  h        },
    40→      { x: -w * 0.75,  y:  h * 0.35 },
    41→      { x: -w * 0.55,  y: -h * 0.1  },
    42→    ];
    43→  }
    44→
    45→  // ─────────────────────────────────────────────────────────────────
    46→  // 생명주기
    47→  // ─────────────────────────────────────────────────────────────────
    48→
    49→  override onCreate(api: GameSceneAPI): void {
    50→    this.startFeverActive = true;
    51→    this.startFeverRain(api);                    // D: 황금 빗줄기 시작
    52→    api.scene.time.delayedCall(6000, () => {
    53→      this.startFeverActive = false;
    54→    });
    55→
    56→    // SSJ 오라 Graphics 미리 생성 (매 80ms clear+redraw)
    57→    this.auraGfx = api.scene.add.graphics().setDepth(85);
    58→  }
    59→
    60→  override onUpdate(api: GameSceneAPI): void {
    61→    const delta = api.scene.game.loop.delta;
    62→
    63→    // A: 불꽃 오라 — 일정 간격마다 파티클 1개 생성
    64→    this.oraTimer += delta;
    65→    const interval = this.legacyModeActive
    66→      ? LegacyAbility.ORA_INTERVAL_LEGACY
    67→      : LegacyAbility.ORA_INTERVAL_NORMAL;
    68→    if (this.oraTimer >= interval) {
    69→      this.oraTimer -= interval;
    70→      this.spawnOraFlame(api);
    71→    }
    72→
    73→    // SSJ 오라 — 80ms마다 스파이크 재생성으로 일렁임 표현
    74→    this.auraRedrawTimer += delta;
    75→    if (this.auraRedrawTimer >= LegacyAbility.AURA_REDRAW_MS) {
    76→      this.auraRedrawTimer -= LegacyAbility.AURA_REDRAW_MS;
    77→      this.redrawAura(api);
    78→    }
    79→
    80→    // 캐릭터 글로우를 플레이어 위치에 맞게 갱신
    81→    if (this.legacyGlow?.active) {
    82→      this.legacyGlow.setPosition(api.player.x, api.player.y);
    83→    }
    84→  }
    85→
    86→  override getTickScore(base: number): number {
    87→    if (!this.legacyModeActive) return base;
    88→    this.accum += base * 0.2;
    89→    const bonus = Math.floor(this.accum);
    90→    this.accum -= bonus;
    91→    return base + bonus;
    92→  }
    93→
    94→  override overrideSpawnPoop(api: GameSceneAPI): boolean {
    95→    if (this.startFeverActive) {
    96→      api.spawnGoldPoop();
    97→      api.spawnGoldPoop();
    98→      return true;
    99→    }
   100→    return false;
   101→  }
   102→
   103→  override onAfterSpawnPoop(api: GameSceneAPI): void {
   104→    const chance = this.legacyModeActive ? 0.4 : 0.2;
   105→    const count  = this.legacyModeActive ? 4   : 2;
   106→    if (Math.random() < chance) {
   107→      this.burnRandomPoops(api, count);
   108→    }
   109→  }
   110→
   111→  override onScoreMilestone(score: number, api: GameSceneAPI): void {
   112→    if (score % 500 === 0 && score > this.lastLegacyScore) {
   113→      this.lastLegacyScore = score;
   114→      this.activateLegacyMode(api);
   115→    }
   116→  }
   117→
   118→  // ─────────────────────────────────────────────────────────────────
   119→  // SSJ 오라 redraw
   120→  // ─────────────────────────────────────────────────────────────────
   121→
   122→  private redrawAura(api: GameSceneAPI): void {
   123→    if (!this.auraGfx?.active) return;
   124→
   125→    const gfx = this.auraGfx;
   126→    const leg  = this.legacyModeActive;
   127→    gfx.clear();
   128→    gfx.setPosition(api.player.x, api.player.y);
   129→
   130→    // 극좌표로 스파이크 24점 생성 (12 tip + 12 valley)
   131→    const NUM_SPIKES = 12;
   132→    const innerR     = leg ? 44 : 32;
   133→    const spikeMin   = leg ? 28 : 16;
   134→    const spikeMax   = leg ? 54 : 34;
   135→    const VERT_RATIO = 1.45; // 세로 방향으로 늘려 불꽃 실루엣
   136→
   137→    const pts: { x: number; y: number }[] = [];
   138→    for (let i = 0; i < NUM_SPIKES * 2; i++) {
   139→      // -π/2에서 시작 → 맨 위 꼭짓점부터 시계 방향
   140→      const angle   = (i / (NUM_SPIKES * 2)) * Math.PI * 2 - Math.PI / 2;
   141→      const isTip   = i % 2 === 0;
   142→
   143→      // 위쪽 스파이크일수록 더 길게 (SSJ 왕관 효과)
   144→      const upBonus = isTip ? Math.max(0, -Math.sin(angle)) * (leg ? 22 : 14) : 0;
   145→
   146→      const r = isTip
   147→        ? innerR + Phaser.Math.Between(spikeMin, spikeMax) + upBonus
   148→        : innerR - Phaser.Math.Between(0, 10);
   149→
   150→      pts.push({
   151→        x: Math.cos(angle) * r,
   152→        y: Math.sin(angle) * r * VERT_RATIO,
   153→      });
   154→    }
   155→
   156→    // 외곽 → 중간 → 코어 3겹 (레거시 모드: 황금, 평상시: 붉은 오렌지)
   157→    if (leg) {
   158→      gfx.fillStyle(0xff8800, 0.10); gfx.fillPoints(pts, true);
   159→      const mid  = pts.map(p => ({ x: p.x * 0.70, y: p.y * 0.70 }));
   160→      gfx.fillStyle(0xffcc00, 0.20); gfx.fillPoints(mid, true);
   161→      const core = pts.map(p => ({ x: p.x * 0.42, y: p.y * 0.42 }));
   162→      gfx.fillStyle(0xffee88, 0.28); gfx.fillPoints(core, true);
   163→    } else {
   164→      gfx.fillStyle(0x991100, 0.07); gfx.fillPoints(pts, true);
   165→      const mid  = pts.map(p => ({ x: p.x * 0.70, y: p.y * 0.70 }));
   166→      gfx.fillStyle(0xff4400, 0.13); gfx.fillPoints(mid, true);
   167→      const core = pts.map(p => ({ x: p.x * 0.42, y: p.y * 0.42 }));
   168→      gfx.fillStyle(0xffaa00, 0.18); gfx.fillPoints(core, true);
   169→    }
   170→  }
   171→
   172→  // ─────────────────────────────────────────────────────────────────
   173→  // A: 상시 불꽃 오라
   174→  // ─────────────────────────────────────────────────────────────────
   175→
   176→  private spawnOraFlame(api: GameSceneAPI): void {
   177→    const scene = api.scene;
   178→    const px    = api.player.x;
   179→    const py    = api.player.y;
   180→    const leg   = this.legacyModeActive;
   181→
   182→    const w = leg ? Phaser.Math.Between(5, 9)  : Phaser.Math.Between(3, 6);
   183→    const h = leg ? Phaser.Math.Between(12, 20) : Phaser.Math.Between(8, 14);
   184→
   185→    const gfx = scene.add.graphics();
   186→
   187→    if (leg) {
   188→      // 레거시 모드: 황금빛 오라
   189→      gfx.fillStyle(0xcc5500, 0.20); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
   190→      gfx.fillStyle(0xff8800, 0.38); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
   191→      gfx.fillStyle(0xffdd00, 0.56); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
   192→    } else {
   193→      // 평상시: 붉은 오렌지 오라
   194→      gfx.fillStyle(0xaa1100, 0.16); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
   195→      gfx.fillStyle(0xff4400, 0.32); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
   196→      gfx.fillStyle(0xffaa00, 0.46); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
   197→    }
   198→
   199→    gfx.setPosition(
   200→      px + Phaser.Math.Between(-14, 14),
   201→      py + Phaser.Math.Between(10, 26), // 발 근처에서 시작
   202→    );
   203→    gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-20, 20)));
   204→    gfx.setDepth(88); // 플레이어 뒤
   205→
   206→    const life = leg ? Phaser.Math.Between(400, 700) : Phaser.Math.Between(280, 500);
   207→    const rise = leg ? Phaser.Math.Between(30, 55)   : Phaser.Math.Between(18, 36);
   208→
   209→    scene.tweens.add({
   210→      targets:  gfx,
   211→      y:        gfx.y - rise,
   212→      alpha:    0,
   213→      scaleX:   0.2,
   214→      scaleY:   0.2,
   215→      duration: life,
   216→      ease:     'Quad.easeOut',
   217→      onComplete: () => { gfx.destroy(); },
   218→    });
   219→  }
   220→
   221→  // ─────────────────────────────────────────────────────────────────
   222→  // B: 화염 추적선 (burn 이벤트 시 플레이어 → 소멸 위치)
   223→  // ─────────────────────────────────────────────────────────────────
   224→
   225→  private drawFireTrail(
   226→    scene: Phaser.Scene,
   227→    fromX: number, fromY: number,
   228→    toList: { x: number; y: number }[],
   229→  ): void {
   230→    if (toList.length === 0) return;
   231→
   232→    const gfx = scene.add.graphics();
   233→    gfx.setDepth(195);
   234→
   235→    for (const { x, y } of toList) {
   236→      // 외곽: 두꺼운 오렌지 반투명
   237→      gfx.lineStyle(3.5, 0xff6600, 0.50);
   238→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   239→
   240→      // 내부: 얇은 노란 선
   241→      gfx.lineStyle(1.5, 0xffee00, 0.75);
   242→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   243→    }
   244→
   245→    scene.tweens.add({
   246→      targets:  gfx,
   247→      alpha:    0,
   248→      duration: 200,
   249→      ease:     'Quad.easeOut',
   250→      onComplete: () => { gfx.destroy(); },
   251→    });
   252→  }
   253→
   254→  // ─────────────────────────────────────────────────────────────────
   255→  // C: 레거시 모드 활성화 — 폭발 연출 + 테두리 글로우
   256→  // ─────────────────────────────────────────────────────────────────
   257→
   258→  private activateLegacyMode(api: GameSceneAPI): void {
   259→    if (this.legacyModeActive) return;
   260→    this.legacyModeActive = true;
   261→    this.accum = 0;
   262→
   263→    const scene = api.scene;
   264→    const cx    = api.player.x;
   265→    const cy    = api.player.y;
   266→
   267→    // ─ 이중 폭발 버스트 (1탄: 주황 → 2탄: 노랑, 화면 전체 커버) ────
   268→    const playBurst = (
   269→      color: number, flashR: number, flashG: number, flashB: number, burstDelay: number,
   270→    ) => {
   271→      scene.time.delayedCall(burstDelay, () => {
   272→        scene.cameras.main.flash(150, flashR, flashG, flashB, true);
   273→
   274→        // 팽창 링 2개 — maxScale 14로 화면 전체 커버 (반경 ~518px)
   275→        [{ rDelay: 0, maxScale: 14 }, { rDelay: 80, maxScale: 11 }].forEach(({ rDelay, maxScale }) => {
   276→          const ring = scene.add.graphics().setDepth(155);
   277→          ring.lineStyle(2.5, color, 0.92);
   278→          ring.strokeEllipse(0, 0, 74, 98);
   279→          ring.setPosition(cx, cy);
   280→          scene.tweens.add({
   281→            targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
   282→            duration: 550, delay: rDelay, ease: 'Quad.easeOut',
   283→            onComplete: () => { ring.destroy(); },
   284→          });
   285→        });
   286→
   287→        // 채움 타원 (빠르게 사라짐)
   288→        const fillGfx = scene.add.graphics().setDepth(154);
   289→        fillGfx.fillStyle(color, 0.28);
   290→        fillGfx.fillEllipse(0, 0, 74, 98);
   291→        fillGfx.setPosition(cx, cy);
   292→        scene.tweens.add({
   293→          targets: fillGfx, alpha: 0, duration: 180, ease: 'Quad.easeOut',
   294→          onComplete: () => { fillGfx.destroy(); },
   295→        });
   296→
   297→        // 파편 8개
   298→        for (let i = 0; i < 8; i++) {
   299→          const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
   300→          const speed = Phaser.Math.FloatBetween(45, 100);
   301→          const sw    = Phaser.Math.Between(5, 13);
   302→          const sh    = Phaser.Math.Between(2, 5);
   303→          const shard = scene.add.graphics().setDepth(156);
   304→          shard.fillStyle(color, 1);
   305→          shard.fillRect(-sw / 2, -sh / 2, sw, sh);
   306→          shard.setPosition(cx, cy).setRotation(angle);
   307→          scene.tweens.add({
   308→            targets: shard,
   309→            x: cx + Math.cos(angle) * speed,
   310→            y: cy + Math.sin(angle) * speed,
   311→            alpha: 0,
   312→            rotation: angle + Phaser.Math.FloatBetween(-1, 1),
   313→            duration: Phaser.Math.Between(280, 460), ease: 'Quad.easeOut',
   314→            onComplete: () => { shard.destroy(); },
   315→          });
   316→        }
   317→      });
   318→    };
   319→
   320→    playBurst(0xff8800, 255, 140,   0,   0); // 1탄: 주황
   321→    playBurst(0xffee44, 255, 220,   0, 210); // 2탄: 노랑
   322→
   323→    // ─ 황금 실루엣 (플레이어 주변 타원) ─────────────────────────
   324→    const silhouette = scene.add.graphics();
   325→    silhouette.fillStyle(0xffdd00, 0.50);
   326→    silhouette.fillEllipse(0, 0, 88, 128);
   327→    silhouette.setPosition(cx, cy).setDepth(157).setAlpha(0);
   328→    scene.tweens.add({
   329→      targets: silhouette, alpha: 1, scaleX: 1.25, scaleY: 1.25,
   330→      duration: 110, ease: 'Quad.easeOut',
   331→      onComplete: () => {
   332→        scene.tweens.add({
   333→          targets: silhouette, alpha: 0, scaleX: 1.8, scaleY: 1.8,
   334→          duration: 300, ease: 'Quad.easeIn',
   335→          onComplete: () => { silhouette.destroy(); },
   336→        });
   337→      },
   338→    });
   339→
   340→    // ─ 화면 전체 불꽃 폭발 (20개) ────────────────────────────────
   341→    const BURST_COLS = [0xff2200, 0xff6600, 0xffaa00, 0xffdd00, 0xffff88];
   342→    for (let i = 0; i < 20; i++) {
   343→      const gfx = scene.add.graphics();
   344→      const w   = Phaser.Math.Between(4, 10);
   345→      const h   = Phaser.Math.Between(10, 22);
   346→      const col = BURST_COLS[Math.floor(Math.random() * BURST_COLS.length)];
   347→
   348→      gfx.fillStyle(col, Phaser.Math.FloatBetween(0.22, 0.50));
   349→      gfx.fillPoints(LegacyAbility.flamePts(w, h), true);
   350→      gfx.fillStyle(0xffee88, Phaser.Math.FloatBetween(0.28, 0.55));
   351→      gfx.fillPoints(LegacyAbility.flamePts(w * 0.4, h * 0.5), true);
   352→
   353→      gfx.setPosition(Phaser.Math.Between(20, 380), Phaser.Math.Between(40, 560));
   354→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-180, 180)));
   355→      gfx.setDepth(158).setAlpha(0);
   356→
   357→      const delay = Phaser.Math.Between(0, 280);
   358→      scene.tweens.add({
   359→        targets: gfx, alpha: 1,
   360→        scaleX: Phaser.Math.FloatBetween(1.2, 1.9),
   361→        scaleY: Phaser.Math.FloatBetween(1.2, 1.9),
   362→        duration: 140, delay, ease: 'Quad.easeOut',
   363→        onComplete: () => {
   364→          scene.tweens.add({
   365→            targets: gfx, alpha: 0, y: gfx.y - Phaser.Math.Between(20, 50),
   366→            duration: Phaser.Math.Between(380, 650), ease: 'Quad.easeIn',
   367→            onComplete: () => { gfx.destroy(); },
   368→          });
   369→        },
   370→      });
   371→    }
   372→
   373→    // ─ 상단 노란빛 그라데이션 (위에서 아래로 퍼지는 빛) ─────────
   374→    this.legacyTopGlow = scene.add.graphics();
   375→    // fillGradientStyle: 상단 alpha 0.28 → 하단 alpha 0 (노란 빛이 위에서 내려오는 느낌)
   376→    this.legacyTopGlow.fillGradientStyle(0xffee00, 0xffee00, 0xffee00, 0xffee00, 0.28, 0.28, 0, 0);
   377→    this.legacyTopGlow.fillRect(0, 0, 400, 220);
   378→    this.legacyTopGlow.setDepth(148);
   379→
   380→    // ─ 캐릭터 노란 글로우 (동심 타원 4겹, 플레이어 추적) ──────────
   381→    // 한 번 그리고 setPosition만 갱신 → 매 프레임 redraw 없음
   382→    this.legacyGlow = scene.add.graphics();
   383→    // 바깥부터 안쪽으로 점점 진해지는 노란 글로우
   384→    this.legacyGlow.fillStyle(0xffee00, 0.08); this.legacyGlow.fillEllipse(0, 0, 110, 140);
   385→    this.legacyGlow.fillStyle(0xffee00, 0.14); this.legacyGlow.fillEllipse(0, 0,  88, 114);
   386→    this.legacyGlow.fillStyle(0xffee00, 0.22); this.legacyGlow.fillEllipse(0, 0,  70,  92);
   387→    this.legacyGlow.fillStyle(0xffdd00, 0.32); this.legacyGlow.fillEllipse(0, 0,  56,  74);
   388→    this.legacyGlow.setPosition(cx, cy).setDepth(87); // 플레이어 바로 뒤
   389→
   390→    // 글로우 + 상단 빛 동시 펄스
   391→    this.legacyPulseTween = scene.tweens.add({
   392→      targets:  [this.legacyGlow, this.legacyTopGlow],
   393→      alpha:    0.55,
   394→      duration: 600, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
   395→    });
   396→
   397→    // 10초 후 종료
   398→    scene.time.delayedCall(10000, () => {
   399→      this.legacyModeActive = false;
   400→      this.legacyPulseTween?.stop();
   401→      this.legacyPulseTween = undefined;
   402→      scene.tweens.add({
   403→        targets: [this.legacyGlow, this.legacyTopGlow],
   404→        alpha: 0, duration: 400, ease: 'Quad.easeOut',
   405→        onComplete: () => {
   406→          this.legacyGlow?.destroy();
   407→          this.legacyGlow = undefined;
   408→          this.legacyTopGlow?.destroy();
   409→          this.legacyTopGlow = undefined;
   410→        },
   411→      });
   412→    });
   413→  }
   414→
   415→  // ─────────────────────────────────────────────────────────────────
   416→  // D: 황금 빗줄기 (피버타임 6초)
   417→  // ─────────────────────────────────────────────────────────────────
   418→
   419→  private startFeverRain(api: GameSceneAPI): void {
   420→    const scene    = api.scene;
   421→    const GOLD     = [0xffcc00, 0xffee44, 0xffd700, 0xffbb33];
   422→    const REPEAT   = Math.floor(6000 / 140) - 1; // 6초 동안, 자동 종료
   423→
   424→    scene.time.addEvent({
   425→      delay:  140,
   426→      repeat: REPEAT,
   427→      callback: () => {
   428→        for (let i = 0; i < 2; i++) {
