     5→  readonly score: number;
     6→  readonly player: Player;
     7→  readonly difficultyLevel: number;
     8→  readonly baseSpeed: number;
     9→  readonly isClassicMode: boolean;
    10→
    11→  readonly poops: Phaser.Physics.Arcade.Group;
    12→  readonly goldPoops: Phaser.Physics.Arcade.Group;
    13→  readonly diamondPoops: Phaser.Physics.Arcade.Group;
    14→  readonly topazPoops: Phaser.Physics.Arcade.Group;
    15→  readonly rainbowPoops: Phaser.Physics.Arcade.Group;
    16→
