     8→ *             + 캐릭터 주변 상시 불꽃 오라(A)
     9→ * - 특수 능력: 500점마다 레거시 모드 10초 발동
    10→ *             — 점수 1.2배 + 화면 전체 불꽃 폭발 + 황금 빗줄기 강화
    11→ *             — 불태우기 강화: 40% 확률로 4개 소멸 / 오라 황금빛으로 강화
    12→ */
    13→export class LegacyAbility extends BaseAbility {
    14→  private startFeverActive = false;
    15→  private legacyModeActive = false;
    16→  private accum           = 0;
    17→  private lastLegacyScore = 0;
    18→  private legacyTopGlow?:    Phaser.GameObjects.Graphics;
    19→  private legacyPulseTween?: Phaser.Tweens.Tween;
    20→  private legacyRainTimer?:  Phaser.Time.TimerEvent;
    21→
    22→  // A: 상시 불꽃 오라
    23→  private oraTimer = 0;
    24→  private static readonly ORA_INTERVAL_NORMAL = 180; // ms
    25→  private static readonly ORA_INTERVAL_LEGACY =  80; // ms
    26→  private static readonly ORA_COLS_NORMAL = [0xff3300, 0xff6600, 0xffaa00];
    27→  private static readonly ORA_COLS_LEGACY = [0xffaa00, 0xffcc00, 0xffee44, 0xffffff];
    28→
    29→  // D: 빗줄기 색상
    30→  private static readonly RAIN_COLS_FEVER  = [0xff8800, 0xffaa00, 0xffcc00, 0xffee00];
    31→  private static readonly RAIN_COLS_LEGACY = [0xff5500, 0xff8800, 0xffaa00, 0xffcc00];
    32→
    33→  // ── 불꽃 물방울 다각형 좌표 ─────────────────────────────────────────
    34→  private static flamePts(w: number, h: number) {
    35→    return [
    36→      { x:  0,         y: -h        },
    37→      { x:  w * 0.55,  y: -h * 0.1  },
    38→      { x:  w * 0.75,  y:  h * 0.35 },
    39→      { x:  w * 0.3,   y:  h        },
    40→      { x: -w * 0.3,   y:  h        },
    41→      { x: -w * 0.75,  y:  h * 0.35 },
    42→      { x: -w * 0.55,  y: -h * 0.1  },
    43→    ];
    44→  }
    45→
    46→  // ── 8각 별 좌표 (빗줄기 공용) ────────────────────────────────────────
    47→  private static starPts(s: number) {
    48→    return [
    49→      { x:  0,       y: -s       }, { x:  s * 0.4, y: -s * 0.4 },
    50→      { x:  s,       y:  0       }, { x:  s * 0.4, y:  s * 0.4 },
    51→      { x:  0,       y:  s       }, { x: -s * 0.4, y:  s * 0.4 },
    52→      { x: -s,       y:  0       }, { x: -s * 0.4, y: -s * 0.4 },
    53→    ];
    54→  }
