   162→  private drawFireTrail(
   163→    scene: Phaser.Scene,
   164→    fromX: number, fromY: number,
   165→    toList: { x: number; y: number }[],
   166→  ): void {
   167→    if (toList.length === 0) return;
   168→
   169→    const gfx = scene.add.graphics();
   170→    gfx.setDepth(195);
   171→
   172→    for (const { x, y } of toList) {
   173→      gfx.lineStyle(3.5, 0xff6600, 0.50);
   174→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   175→      gfx.lineStyle(1.5, 0xffee00, 0.75);
   176→      gfx.beginPath(); gfx.moveTo(fromX, fromY); gfx.lineTo(x, y); gfx.strokePath();
   177→    }
   178→
   179→    scene.tweens.add({
   180→      targets: gfx, alpha: 0, duration: 200, ease: 'Quad.easeOut',
   181→      onComplete: () => { gfx.destroy(); },
   182→    });
   183→  }
