   404→
   405→  private playBurnEffect(scene: Phaser.Scene, cx: number, cy: number): void {
   406→    const flash = scene.add.graphics();
   407→    flash.fillStyle(0xff7700, 0.60); flash.fillCircle(0, 0, 17);
   408→    flash.fillStyle(0xffee88, 0.45); flash.fillCircle(0, 0, 9);
   409→    flash.setPosition(cx, cy).setDepth(202);
   410→    scene.tweens.add({
   411→      targets: flash, scaleX: 2.8, scaleY: 2.8, alpha: 0,
   412→      duration: 190, ease: 'Quad.easeOut',
   413→      onComplete: () => { flash.destroy(); },
   414→    });
   415→
   416→    for (let i = 0; i < 10; i++) {
   417→      const gfx = scene.add.graphics();
   418→      const w   = Phaser.Math.Between(5, 11);
   419→      const h   = Phaser.Math.Between(14, 27);
   420→
   421→      gfx.fillStyle(0xaa1100, 0.25); gfx.fillPoints(LegacyAbility.flamePts(w,        h       ), true);
   422→      gfx.fillStyle(0xff4400, 0.48); gfx.fillPoints(LegacyAbility.flamePts(w * 0.70, h * 0.76), true);
   423→      gfx.fillStyle(0xffcc00, 0.68); gfx.fillPoints(LegacyAbility.flamePts(w * 0.40, h * 0.50), true);
   424→
   425→      gfx.setPosition(
   426→        cx + Phaser.Math.Between(-15, 15),
   427→        cy + Phaser.Math.Between(-10, 10),
   428→      );
   429→      gfx.setRotation(Phaser.Math.DegToRad(Phaser.Math.Between(-28, 28)));
   430→      gfx.setDepth(200);
   431→
   432→      const rise = Phaser.Math.Between(48, 88);
   433→      const dur  = Phaser.Math.Between(500, 900);
   434→
   435→      scene.tweens.add({
   436→        targets: gfx, y: gfx.y - rise * 0.38, scaleX: 1.45, scaleY: 1.45,
   437→        duration: dur * 0.35, ease: 'Quad.easeOut',
   438→        onComplete: () => {
   439→          scene.tweens.add({
   440→            targets: gfx, y: gfx.y - rise * 0.62, scaleX: 0, scaleY: 0, alpha: 0,
   441→            duration: dur * 0.65, ease: 'Quad.easeIn',
   442→            onComplete: () => { gfx.destroy(); },
   443→          });
   444→        },
   445→      });
   446→    }
   447→
   448→    const EMBER_COLS = [0xff5500, 0xff8800, 0xffbb00];
   449→    for (let i = 0; i < 8; i++) {
   450→      const gfx = scene.add.graphics();
   451→      const s   = Phaser.Math.Between(2, 5);
   452→      const col = Phaser.Utils.Array.GetRandom(EMBER_COLS) as number;
