private handleDiamondCollected(poop: Phaser.Physics.Arcade.Sprite) {
  if (this.gameOver) return;
  poop.destroy();
  this.diamondCollected++;
  const bonus = this.ability.onCollectSpecial('diamond');
  const total = 40 + bonus;
  this.updateScore(total);
  if (!this.isFeverTime) {
    const label = bonus > 0 ? `💎 다이아똥 +${total}점! (+${bonus}) 💎` : '💎 다이아똥 +40점! 💎';
    const diamondText = this.add.text(200, 100, label, {
      fontSize: '28px', color: '#00FFFF', fontStyle: 'bold',
      stroke: '#000', strokeThickness: 4
    }).setOrigin(0.5);
    this.time.delayedCall(1000, () => diamondText.destroy());
  }
}

